-- Seed the database-backed price and food-reference catalogue from the reviewed source snapshots.
ON CONFLICT (catalogue, entry_key) DO UPDATE SET data = EXCLUDED.data, updated_at = now();

UPDATE public.price_reference_data
SET data = data || '{"region":"NCR","source":"DA-AMAS weekly average","currency":"PHP","sourceCountry":"PH"}'::jsonb
WHERE catalogue = 'da_catalog';

UPDATE public.price_reference_data
SET data = data || '{"source":"Metro official online store","region":"Philippines / online store","currency":"PHP","sourceCountry":"PH"}'::jsonb
WHERE catalogue = 'metro_source';

UPDATE public.price_reference_data
SET data = data || jsonb_build_object(
  'region',
  CASE WHEN data->>'host' = 'jelexie.ph'
    THEN 'Tarlac brand / online store'
    ELSE 'Philippines / online store'
  END,
  'currency', 'PHP',
  'sourceCountry', 'PH'
)
WHERE catalogue = 'shopify_source';

UPDATE public.price_reference_data
SET data = data || '{"region":"NCR","currency":"PHP","sourceCountry":"PH"}'::jsonb
WHERE catalogue = 'retail_special' AND entry_key = 'tocino';

UPDATE public.price_reference_data
SET data = data || '{"region":"Philippines / online store","currency":"PHP","sourceCountry":"PH","note":"Whole bird includes bones and skin; edible breast yield is not measured."}'::jsonb
WHERE catalogue = 'retail_special' AND entry_key = 'whole_duck';

UPDATE public.price_reference_data
SET data = data || '{"region":"Panglao, Bohol / Philippine retailer","currency":"PHP","sourceCountry":"PH","unitCode":"KGM","unitValue":1}'::jsonb
WHERE catalogue = 'retail_special' AND entry_key = 'duck_breast';
